def audit_context(sequence, target, candidates, view, rng):
    history = sequence[sequence != 0]
    if len(history) < 3:
        return {'eligible': False, 'reason': 'history_too_short'}
    k = min(3, (len(history) - 1) // 2)
    variants = {
        'original': history,
        'recent_removed': history[:-k],
        'oldest_removed': history[k:],
    }
    for repeat in range(3):
        variants[f'shuffle_{repeat}'] = concat(
            permute(history[:-1], rng), history[-1:])
    ranks = {}
    for name, items in variants.items():
        seq = left_pad(items, original_length=len(sequence))
        features = view.log2feats(seq[None, :])
        last = max_index_where(seq != 0)
        scores = view.predict_score(features[:, last, :], candidates)
        ranks[name] = target_rank(scores, target, fixed_host_tie_rule)
    return paired_rank_rr_and_hit_changes(ranks, cutoff=10)

